import CoreData
import Foundation
extension CoreDataModel {
 func fetchTransactionTemplates(in context: NSManagedObjectContext? = nil) -> [TransactionTemplateEntity] { let c=context ?? self.context; return c.performAndWait { let r=TransactionTemplateEntity.fetchRequest(); r.sortDescriptors=[NSSortDescriptor(key:"order",ascending:true),NSSortDescriptor(key:"createdAt",ascending:true)]; return (try? c.fetch(r)) ?? [] } }
 func addTransactionTemplate(_ value: TransactionTemplateLocal) { context.performAndWait { guard value.amount > 0, !value.name.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty, let d=NSEntityDescription.entity(forEntityName:"TransactionTemplateEntity",in:context) else{return}; let t=TransactionTemplateEntity(entity:d,insertInto:context); t.id=UUID(); t.name=value.name.trimmingCharacters(in:.whitespacesAndNewlines); t.amount=value.amount; t.isIncome=value.isIncome; t.note=value.note; t.order=value.order; t.createdAt=.now; t.modifiedAt=.now; if let id=value.categoryID { t.category=findCategory(id,in:context) }; manager.save() } }
 func editTransactionTemplate(_ template: TransactionTemplateEntity, with value: TransactionTemplateLocal) { context.performAndWait { guard value.amount > 0, !value.name.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty else{return}; template.name=value.name.trimmingCharacters(in:.whitespacesAndNewlines); template.amount=value.amount; template.isIncome=value.isIncome; template.note=value.note; template.order=value.order; template.modifiedAt=.now; template.category=value.categoryID.flatMap { findCategory($0,in:context) }; manager.save() } }
 func deleteTransactionTemplate(_ template: TransactionTemplateEntity) { context.performAndWait { context.delete(template); manager.save() } }
 func reorderTransactionTemplates(_ templates: [TransactionTemplateEntity]) { context.performAndWait { for (index, template) in templates.enumerated(){ template.order=Int32(index); template.modifiedAt=.now }; manager.save() } }
}
